let liveTrialRecords = [];
const activeTrialStatuses = new Set(['RECRUITING','NOT_YET_RECRUITING','ACTIVE_NOT_RECRUITING','ENROLLING_BY_INVITATION']);

function geneDirectoryEnglish(){
  return `<section class="gene-directory" aria-labelledby="gene-directory-title"><div class="direction-title"><p class="eyebrow">Monogenic immune conditions and genetic clues</p><h2 id="gene-directory-title">A mechanism-led gene explorer.</h2><p>CVID is an umbrella diagnosis, not one single genetic disease. These examples help explain why genetic findings can change classification, monitoring or treatment discussions. This is not a diagnostic gene panel.</p></div><label class="gene-search">Search a gene or pathway<input id="gene-search" type="search" placeholder="Try CTLA4, PI3K or B-cell"></label><div class="gene-catalogue">${geneCatalogue.map(([gene,pathway,meaning])=>`<article data-gene-entry="${`${gene} ${pathway} ${meaning}`.toLowerCase()}"><span>${pathway}</span><h3>${gene}</h3><p>${meaning}</p></article>`).join('')}</div><p class="gene-source">Classification context: <a href="https://iuis.org/committees/iei/" target="_blank" rel="noopener">IUIS 2024 IEI classification ↗</a> · Condition records: <a href="https://www.ncbi.nlm.nih.gov/gtr/conditions/C3149378/" target="_blank" rel="noopener">NIH Genetic Testing Registry ↗</a></p></section>`;
}

function normaliseLiveTrial(study){
  const p=study.protocolSection||{},id=p.identificationModule||{},status=p.statusModule||{},design=p.designModule||{},sponsor=p.sponsorCollaboratorsModule||{},contacts=p.contactsLocationsModule||{},eligibility=p.eligibilityModule||{},description=p.descriptionModule||{};
  const locations=(contacts.locations||[]).map(x=>({facility:x.facility||'',city:x.city||'',state:x.state||'',country:x.country||'',status:x.status||''}));
  return {id:id.nctId||'',title:id.briefTitle||id.officialTitle||'Untitled study',officialTitle:id.officialTitle||'',status:status.overallStatus||'UNKNOWN',updated:status.studyFirstPostDateStruct?.date?status.lastUpdatePostDateStruct?.date||status.studyFirstPostDateStruct.date:'',type:design.studyType||'',phase:(design.phases||[]).join(', '),sponsor:sponsor.leadSponsor?.name||'Not listed',summary:description.briefSummary||'',minimumAge:eligibility.minimumAge||'',maximumAge:eligibility.maximumAge||'',sex:eligibility.sex||'ALL',criteria:eligibility.eligibilityCriteria||'',locations,source:`https://clinicaltrials.gov/study/${id.nctId||''}`};
}

function formatTrialStatus(status){ return ({RECRUITING:'Recruiting',NOT_YET_RECRUITING:'Not yet recruiting',ACTIVE_NOT_RECRUITING:'Active, not recruiting',ENROLLING_BY_INVITATION:'Enrolling by invitation',COMPLETED:'Completed'}[status]||status.replaceAll('_',' ').toLowerCase()); }

function renderLiveTrials(records){
  const target=document.querySelector('#clinical-trials-live'); if(!target) return;
  const active=records.filter(x=>activeTrialStatuses.has(x.status)).slice(0,18);
  target.innerHTML=`<div class="live-heading"><div><p class="eyebrow">Live public records</p><h2>Clinical studies connected to CVID.</h2><p>Records are retrieved from ClinicalTrials.gov and shown for discovery only. Open the official record for complete eligibility and contact information.</p></div><span class="data-state live">Live · ${active.length} active records</span></div><div class="trial-browser-list">${active.map(x=>`<article><div class="study-meta"><span>${formatTrialStatus(x.status)}</span><span>${x.type}${x.phase?` · ${x.phase}`:''}</span><span>${x.id}</span></div><h3>${x.title}</h3><p>${x.summary||'See the official record for the study summary.'}</p><dl><div><dt>Lead organisation</dt><dd>${x.sponsor}</dd></div><div><dt>Age</dt><dd>${x.minimumAge||'Not listed'} – ${x.maximumAge||'Not listed'}</dd></div><div><dt>Locations</dt><dd>${[...new Set(x.locations.map(l=>l.country).filter(Boolean))].join(', ')||'See official record'}</dd></div><div><dt>Last updated</dt><dd>${x.updated||'See official record'}</dd></div></dl><a href="${x.source}" target="_blank" rel="noopener">Open official ClinicalTrials.gov record ↗</a></article>`).join('')}</div>`;
}

async function loadClinicalTrials(){
  const status=document.querySelector('#trial-data-status'); if(status) status.textContent='Loading current ClinicalTrials.gov records…';
  try{
    const response=await fetch('https://clinicaltrials.gov/api/v2/studies?query.cond=Common%20Variable%20Immunodeficiency&pageSize=100&format=json');
    if(!response.ok) throw new Error(`HTTP ${response.status}`);
    const payload=await response.json(); liveTrialRecords=(payload.studies||[]).map(normaliseLiveTrial);
    renderLiveTrials(liveTrialRecords);
    if(status) status.textContent=`Live source connected · ${liveTrialRecords.filter(x=>activeTrialStatuses.has(x.status)).length} active public records found`;
  }catch(error){
    if(status) status.textContent='Live source temporarily unavailable · using the verified fallback records shown below';
    const target=document.querySelector('#clinical-trials-live');
    if(target) target.querySelector('.data-state')?.classList.remove('live');
  }
}

