app.addEventListener('click',event=>{const button=event.target.closest('[data-follow-centre]');if(!button)return;const name=button.dataset.followCentre,count=Number(button.dataset.demoCount);const active=followedCentres.has(name);active?followedCentres.delete(name):followedCentres.add(name);button.textContent=active?(language==='zh'?'关注这个中心':'Follow this centre'):(language==='zh'?'已关注 · 可接收研究提醒':'Following · research alerts available');button.classList.toggle('followed',!active);button.previousElementSibling.querySelector('strong').textContent=count+(active?0:1);});
app.addEventListener('click',event=>{const filter=event.target.closest('[data-result-filter]');if(!filter)return;document.querySelectorAll('[data-result-filter]').forEach(x=>x.classList.remove('selected'));filter.classList.add('selected');document.querySelectorAll('.result-item').forEach(item=>item.hidden=filter.dataset.resultFilter!=='all'&&item.dataset.resultType!==filter.dataset.resultFilter);});
app.addEventListener('click',event=>{const tabButton=event.target.closest('[data-atlas-tab]');if(!tabButton)return;document.querySelectorAll('[data-atlas-tab]').forEach(x=>x.classList.remove('selected'));tabButton.classList.add('selected');document.querySelectorAll('[data-atlas-panel]').forEach(panel=>panel.hidden=panel.dataset.atlasPanel!==tabButton.dataset.atlasTab);});
app.addEventListener('click',event=>{const trigger=event.target.closest('[data-scroll-target]');if(!trigger)return;const target=document.getElementById(trigger.dataset.scrollTarget);if(!target)return;if(target.tagName==='DETAILS')target.open=true;target.scrollIntoView({behavior:'smooth',block:'start'});});
app.addEventListener('submit',event=>{if(event.target.id!=='interest-form')return;event.preventDefault();const formData=new FormData(event.target),topics=formData.getAll('topic'),mode=formData.get('contact-mode'),email=formData.get('email'),feedback=event.target.querySelector('.interest-feedback');if(!topics.length){feedback.textContent=language==='zh'?'请至少选择一个研究方向。':'Choose at least one research topic.';return;}if(mode==='email'&&!email){feedback.textContent=language==='zh'?'选择邮件通知时需要填写邮箱。':'Enter an email for email alerts.';return;}feedback.textContent=language==='zh'?(mode==='anonymous'?'演示完成。信息未保存、未发送，也不会收到通知。':'会员登记演示完成；真实版本会创建私人账户，并按你的选择通过站内信或邮件通知。'):(mode==='anonymous'?'Demo complete. Nothing has been saved or sent, and no alerts will be sent.':'Member registration demo complete; the live version would create a private account and send your chosen alerts.');event.target.querySelector('button').disabled=true;});

function render() { const page=location.hash.slice(1)||'home'; const note=page.match(/^research-note-(\d+)$/); const view=note?()=>researchNote(Number(note[1])):({home,overview,molecules:()=>nav('overview')+moleculeDirectory(language==='en')+footer(),centres:centresV2,research,'case-study':caseStudy}[page]||home); app.innerHTML=view(); document.querySelector('.language-toggle').addEventListener('click',()=>{language=language==='zh'?'en':'zh';render();}); document.querySelector('.menu-button')?.addEventListener('click',e=>{const open=e.currentTarget.getAttribute('aria-expanded')==='true';e.currentTarget.setAttribute('aria-expanded',String(!open));document.querySelector('.main-nav').classList.toggle('open',!open);}); document.querySelectorAll('[data-country]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-country]').forEach(b=>b.classList.remove('selected'));btn.classList.add('selected');const country=btn.dataset.country;let visible=0;document.querySelectorAll('[data-centre-country]').forEach(card=>{const show=country==='全部'||card.dataset.centreCountry===country;card.hidden=!show;if(show)visible++;});const count=document.querySelector('#centre-count');if(count)count.textContent=`${visible} ${language==='zh'?'个代表性机构':'representative institutions'}`;})); const geneSearch=document.querySelector('#gene-search'); if(geneSearch) geneSearch.addEventListener('input',()=>{const query=geneSearch.value.trim().toLowerCase();document.querySelectorAll('[data-gene-entry]').forEach(card=>card.hidden=query&&!card.dataset.geneEntry.includes(query));}); }
window.addEventListener('hashchange',renderV2);renderV2();
